    make(7, "功的國際單位焦耳（J）可用哪些基本組合表示？", {"A": "N／m", "B": "N·m", "C": "kg／m", "D": "m／s"}, "B", "作功 W＝Fd，力的單位是牛頓、位移的單位是公尺，因此 1 J＝1 N·m，選 B。", "從定義式檢查單位，不靠背誦孤立符號。", ["寫出作功公式 W＝Fd。", "確認 F 的單位是 N。", "確認 d 的單位是 m。", "相乘後得到 N·m。", "這個組合就是 J，選 B。"], "easy"),
    make(8, "人用力推一面固定不動的牆，雖然自己感到疲累，但牆受到這個推力所作的功為何？", {"A": "正功，因為推力很大", "B": "負功，因為人感到疲累", "C": "零功，因為牆沒有位移", "D": "無限大，因為推的時間很久"}, "C", "對牆而言位移 d＝0，因此 W＝Fd＝0；人的生理耗能不等於牆獲得的機械功，選 C。", "明確指定研究對象，並檢查該物體是否真的發生位移。", ["把牆當作研究對象。", "確認牆沒有移動，d＝0。", "代入 W＝Fd。", "不論推力或時間多大，牆的位移仍是零。", "所以牆受到的推力作零功，選 C。"], "easy"),
    make(9, "以大小為 F 的力斜向上拉箱子，使箱子水平前進距離 d。計算此拉力對箱子作功時，應使用哪一項？", {"A": "F 的鉛直分量乘以 d", "B": "F 的水平分量乘以 d", "C": "F 的大小除以 d", "D": "箱子的重量乘以 d"}, "B", "只有與位移同方向的力分量能作功；水平前進時 W＝F cosθ × d，選 B。", "將力分解後，只保留平行於位移的分量。", ["確認箱子位移為水平距離 d。", "把斜向力分成水平與鉛直分量。", "水平分量與位移平行。", "鉛直分量與位移垂直，對此位移作零功。", "因此使用水平分量乘 d，選 B。"], "medium"),
    make(10, "木箱受 12 N 水平拉力向右移動 5 m，反向摩擦力為 4 N，其他水平力可忽略。木箱動能增加多少？", {"A": "20 J", "B": "40 J", "C": "60 J", "D": "80 J"}, "B", "拉力作功 12×5＝60 J，摩擦力作功 −4×5＝−20 J，合力作功為 40 J，依功—能定理動能增加 40 J，選 B。", "分別算各力作功，再相加取得合力功，最後連到動能變化。", ["計算拉力功：12×5＝60 J。", "計算摩擦力功：−4×5＝−20 J。", "合力功＝60−20＝40 J。", "依 W合＝ΔK，動能增加 40 J。", "所以選 B。"], "hard"),
